// Top 10 VMs ranked by average CPU utilization over the last hour.
// Source: VM Insights "InsightsMetrics" table (Azure Monitor Agent + VM Insights DCR).
// Use for: quickly spotting hot VMs.
InsightsMetrics
| where TimeGenerated > ago(1h)
| where Namespace == "Processor" and Name == "UtilizationPercentage"
| summarize CpuPct = avg(Val) by Computer
| top 10 by CpuPct desc

// Available memory (MB) per VM over the last hour, bucketed in 5-minute bins.
// Source: VM Insights "InsightsMetrics".
// Use for: spotting memory pressure trends and saw-tooth patterns.
InsightsMetrics
| where TimeGenerated > ago(1h)
| where Namespace == "Memory" and Name == "AvailableMB"
| summarize avg(Val) by Computer, bin(TimeGenerated, 5m)
| render timechart

// Last heartbeat per VM with "minutes since" — useful liveness check.
// Source: "Heartbeat" table, written by AMA on every VM.
// Use for: detecting stopped / unreachable VMs (anything > 5 min is suspicious).
Heartbeat
| summarize LastHeartbeat = max(TimeGenerated) by Computer, OSType
| extend MinutesSince = datetime_diff("minute", now(), LastHeartbeat)
| order by MinutesSince desc

// Total container restarts per pod over the last 24 hours.
// Source: Container Insights "KubePodInventory".
// Use for: catching crashloops and unstable workloads.
KubePodInventory
| where TimeGenerated > ago(24h)
| summarize Restarts = sum(toint(ContainerRestartCount)) by Namespace, ControllerName, Name
| where Restarts > 0
| order by Restarts desc

// stdout/stderr lines from any AKS container that contain error-like keywords.
// Source: Container Insights "ContainerLogV2" (new high-perf log table).
// Use for: triaging app-level errors without kubectl logs.
ContainerLogV2
| where TimeGenerated > ago(1h)
| where LogMessage has_any ("error","exception","fatal","panic")
| project TimeGenerated, Computer, PodName, ContainerName, LogMessage
| order by TimeGenerated desc
| take 100

// AKS node-level CPU and memory perf counters over the last hour.
// Source: Container Insights "Perf" table (cluster-level counters).
// Use for: correlating noisy-neighbor workloads with node pressure.
Perf
| where TimeGenerated > ago(1h)
| where ObjectName in ("K8SNode","Memory","Processor")
| where CounterName in ("cpuUsageNanoCores","memoryWorkingSetBytes","% Processor Time")
| summarize avg(CounterValue) by Computer, CounterName, bin(TimeGenerated, 5m)
| render timechart

// Stacked column chart of HTTP status codes returned by App Services in this RG.
// Source: "AppServiceHTTPLogs" diagnostic logs (sent to LAW via policy).
// Use for: visualising 2xx/4xx/5xx mix during incidents or load tests.
AppServiceHTTPLogs
| where TimeGenerated > ago(1h)
| summarize Hits = count() by ScStatus, bin(TimeGenerated, 5m)
| render columnchart

// Top 50 slowest App Service requests in the last hour by TimeTaken (ms).
// Source: "AppServiceHTTPLogs".
// Use for: latency hunting before drilling into App Insights traces.
AppServiceHTTPLogs
| where TimeGenerated > ago(1h)
| project TimeGenerated, CsHost, CsUriStem, ScStatus, TimeTaken
| top 50 by TimeTaken desc

// Recent successful write/delete/action operations against resources in this RG.
// Source: "AzureActivity" (subscription activity log streamed to LAW).
// Use for: change-correlation during incident response ("what changed before this broke?").
AzureActivity
| where TimeGenerated > ago(24h)
| where OperationNameValue has_any ("write","delete","action")
| where ActivityStatusValue == "Success"
| project TimeGenerated, Caller, OperationNameValue, ResourceProviderValue, _ResourceId
| order by TimeGenerated desc

[format('// CROSS-WORKSPACE: correlate App Insights failed-request count with VM CPU%.
// Sources: workspace("{0}").AppRequests  +  central LAW InsightsMetrics.
// Both series are normalised to 0–100 (% of their own peak) so they fit one Y-axis.
// Use for: cross-team incident review (devs + ops on one chart).
let appiFailed = workspace("{1}").AppRequests
  | where TimeGenerated > ago(1h) and Success == false
  | summarize Failed = todouble(count()) by bin(TimeGenerated, 5m);
let vmCpu = InsightsMetrics
  | where TimeGenerated > ago(1h)
  | where Namespace == "Processor" and Name == "UtilizationPercentage"
  | summarize CpuPct = todouble(avg(Val)) by bin(TimeGenerated, 5m);
let joined = appiFailed
  | join kind=fullouter vmCpu on TimeGenerated
  | project TimeGenerated = coalesce(TimeGenerated, TimeGenerated1),
            Failed = coalesce(Failed, todouble(0)),
            CpuPct = coalesce(CpuPct, todouble(0));
let maxFailed = toscalar(joined | summarize max(Failed));
let maxCpu    = toscalar(joined | summarize max(CpuPct));
joined
| extend FailedNorm = iff(maxFailed > 0, 100.0 * Failed / maxFailed, todouble(0)),
         CpuNorm    = iff(maxCpu    > 0, 100.0 * CpuPct    / maxCpu,    todouble(0))
| project TimeGenerated,
          ["Failed requests (% of peak)"] = FailedNorm,
          ["VM CPU (% of peak)"]          = CpuNorm
| order by TimeGenerated asc
| render timechart with (ytitle="% of peak")', parameters('appInsightsLawName'), parameters('appInsightsLawName'))]

[format('// CROSS-WORKSPACE: unify three signals into one chronological feed:
//   1) App Service HTTP layer  (AppServiceHTTPLogs in this LAW)
//   2) App Insights request    (AppRequests in the AppI LAW via workspace())
//   3) AKS load-gen pod logs   (ContainerLogV2 in this LAW)
// Use for: storytelling during a demo or post-mortem — show the same event from 3 angles.
union
  (AppServiceHTTPLogs | where TimeGenerated > ago(1h) | project TimeGenerated, Source = "AppServiceHTTPLogs", Detail = strcat(CsMethod, " ", CsUriStem, " -> ", ScStatus)),
  (workspace("{0}").AppRequests | where TimeGenerated > ago(1h) | project TimeGenerated, Source = "AppI.AppRequests", Detail = strcat(Name, " | success=", Success, " | duration_ms=", DurationMs)),
  (ContainerLogV2 | where TimeGenerated > ago(1h) | where PodName has "loadgen" | project TimeGenerated, Source = "AKS.ContainerLogV2", Detail = LogMessage)
| order by TimeGenerated desc
| take 200', parameters('appInsightsLawName'))]

// Ingestion volume in GB per table for the last 7 days.
// Source: "Usage" — built-in billing-meter table in every LAW.
// Use for: cost reviews, picking candidates for DCR transformations or Basic Logs.
Usage
| where TimeGenerated > ago(7d)
| where IsBillable == true
| summarize GB = sum(Quantity) / 1024 by DataType, bin(TimeGenerated, 1d)
| order by TimeGenerated desc, GB desc
| render columnchart kind=stacked

// Proves the FEATURE 1 workspace transformation on AzureActivity.
// The DCR (dcr-amlab-workspace-transforms) does TWO things to every row:
//   (a) FILTER:  drops "/read" operations (Get / List / Read)   <- saves $$ at ingest.
//   (b) ENRICH:  adds a "FilteredBy" key to the dynamic Properties column.
//
// EXPECTED RESULT (single row), after the transform has been active for >= 1 min:
//   RowsTotal                = the number of AzureActivity rows in last 1h
//   RowsWithReadOperation    = 0     (filter dropped them at ingest)
//   RowsWithFilteredBy       = RowsTotal  (the enrich marker is on EVERY kept row)
//   DistinctOperations       = a short list of non-/read operations
AzureActivity
| where TimeGenerated > ago(1h)
| extend FilteredBy = tostring(parse_json(Properties).FilteredBy)
| summarize
    RowsTotal             = count(),
    RowsWithReadOperation = countif(tolower(OperationNameValue) endswith "/read"),
    RowsWithFilteredBy    = countif(FilteredBy == "amlab-workspace-transform"),
    DistinctOperations    = strcat_array(make_set(OperationNameValue, 10), ", ")

// 20 most recent AzureActivity rows showing the FEATURE 1 transform in action.
// You should see EVERY row with:
//   - OperationNameValue does NOT end with "/read"    (filter passed)
//   - Properties.FilteredBy == "amlab-workspace-transform"  (enrich ran)
//   - Properties.FilteredAt is a recent timestamp     (enrich ran, second prop)
AzureActivity
| where TimeGenerated > ago(1h)
| extend FilteredBy = tostring(parse_json(Properties).FilteredBy),
         FilteredAt = tostring(parse_json(Properties).FilteredAt)
| project TimeGenerated, Caller, OperationNameValue, ActivityStatusValue, FilteredBy, FilteredAt
| order by TimeGenerated desc
| take 20

// Custom log data sent via the Logs Ingestion API (scripts/send-custom-logs.ps1).
// Source: "SecurityAudit_CL" — a custom table in this workspace.
// Use for: proving external systems can push data into Log Analytics.
SecurityAudit_CL
| where TimeGenerated > ago(1h)
| project TimeGenerated, EventType, Severity, UserPrincipal, SourceIP, Action, Result, Details
| order by TimeGenerated desc

// Aggregated view of custom security audit events by type and severity.
// Source: "SecurityAudit_CL".
// Use for: showing KQL analytics on custom ingested data.
SecurityAudit_CL
| where TimeGenerated > ago(24h)
| summarize EventCount = count(), DistinctUsers = dcount(UserPrincipal) by EventType, Severity
| order by EventCount desc

// Compare raw Perf data volume vs the pre-aggregated Perf_Hourly_CL summary.
// Shows the cost win: same answer from orders-of-magnitude fewer rows.
// Source: "Perf" (raw) + "Perf_Hourly_CL" (summary).
let rawStats = Perf
  | where TimeGenerated > ago(24h)
  | where ObjectName in ("Processor","Memory","LogicalDisk")
  | summarize RawRowCount = count(), RawDistinctComputers = dcount(Computer);
let summaryStats = Perf_Hourly_CL
  | where TimeGenerated > ago(24h)
  | summarize SummaryRowCount = count(), SummaryDistinctComputers = dcount(Computer);
rawStats | extend placeholder = 1
| join kind=inner (summaryStats | extend placeholder = 1) on placeholder
| project RawRowCount, SummaryRowCount,
          CompressionRatio = strcat("1:", tolong(RawRowCount / max_of(SummaryRowCount, 1))),
          RawDistinctComputers, SummaryDistinctComputers

// Call the vmHealth() saved function to get traffic-light status for all VMs.
// This function is defined in kql-functions.bicep and stored in the workspace.
// Use for: showing reusable KQL abstractions.
vmHealth()
| order by case(Status == "Red", 0, Status == "Orange", 1, 2) asc

// Call the envHealth() function for a combined traffic-light view across
// VMs, AKS pods, and App Insights. Cross-workspace, single function call.
// Use for: showing how functions compose and abstract complexity.
envHealth()

// Granular RBAC demo: run this query to see SecurityAudit_CL events.
// With full access: all rows visible (all severities).
// With table-level ABAC: only SecurityAudit_CL is queryable.
// With row-level ABAC (Severity==Critical): only Critical rows appear.
// Use for: proving ABAC table/row-level filtering.
SecurityAudit_CL
| where TimeGenerated > ago(24h)
| summarize EventCount = count() by Severity, EventType
| order by Severity asc, EventType asc

// Hop-by-hop network health from each lab VM to the App Service HTTPS endpoint.
// Source: "NWConnectionMonitorTestResult" — written by Network Watcher Connection Monitor.
// Use for: spotting transient or geographic packet-loss / latency issues.
NWConnectionMonitorTestResult
| where TimeGenerated > ago(1h)
| summarize ChecksFailedPct = round(100.0 * countif(TestResult != "Pass") / count(), 2),
            AvgRttMs = round(avg(AvgRoundTripTimeMs), 1)
          by SourceName, DestinationName, bin(TimeGenerated, 5m)
| order by TimeGenerated desc, SourceName asc

// Every key-vault data-plane operation (get/list/set) — the data behind Key Vault Insights.
// Source: "AzureDiagnostics" with ResourceType KEYVAULTS.
// Use for: tracking secret access, expiring credential rotation, suspicious activity.
AzureDiagnostics
| where ResourceType == "VAULTS" and Category == "AuditEvent"
| where TimeGenerated > ago(1h)
| summarize Calls = count() by OperationName, ResultType, identity_claim_appid_g, CallerIPAddress
| order by Calls desc

// Storage Insights backing data: transaction counts + total request units per API.
// Source: "AzureMetrics" with ResourceProvider MICROSOFT.STORAGE.
// Use for: top APIs, throttling investigations, capacity trending.
AzureMetrics
| where ResourceProvider == "MICROSOFT.STORAGE"
| where TimeGenerated > ago(1h)
| where MetricName in ("Transactions", "SuccessE2ELatency", "Ingress", "Egress")
| summarize Avg = avg(Average), Total = sum(Total) by MetricName, bin(TimeGenerated, 5m)
| render timechart

// Sentinel incidents raised in the last 24h. Empty if Sentinel was disabled at deploy.
// Source: "SecurityIncident" (Sentinel-managed table on the central LAW).
SecurityIncident
| where TimeGenerated > ago(24h)
| project TimeGenerated, IncidentNumber, Title, Severity, Status, CreatedTime, ClassificationReason
| order by TimeGenerated desc

