variables.$fxv#2:
// Estimated cost trend, per day (last 7 days)
// -------------------------------------------------------------------
// Purpose:  Daily spend trend for the FinOps demo — total tokens, calls
//           and estimated USD per day across all agents. Use it to spot
//           day-over-day growth or spikes and to seed a budget threshold.
// Source:   Application Insights `dependencies` table (GenAI spans).
// Filter:   isnotempty(gen_ai.agent.name) — attributable spans only.
// Pricing:  gpt-5-mini GlobalStandard list price (input $0.25/1M,
//           output $2.00/1M). Replace with your current per-model rates.
// Caveat:   Token-derived ESTIMATE — excludes discounts/PTU/cached input;
//           reconcile with Azure Cost Management. Widen ago(7d) as needed.

dependencies
| where timestamp > ago(7d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok  = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"])
| summarize prompt=sum(inTok), completion=sum(outTok), calls=count()
          by day=bin(timestamp, 1d)
| extend est_usd = round(prompt/1000000.0*0.25 + completion/1000000.0*2.00, 4)
| order by day asc

variables.$fxv#3:
// Cost per successful request, by agent (last 24h)
// -------------------------------------------------------------------
// Purpose:  Unit economics that join COST + RELIABILITY. Failed/retried
//           calls still burn tokens, so this divides estimated spend by the
//           number of *successful* requests — the true price of a good answer.
// Source:   Application Insights `dependencies` (GenAI spans). Uses the
//           native `success` column for pass/fail.
// Pricing:  gpt-5-mini GlobalStandard list price (input $0.25/1M,
//           output $2.00/1M). Replace with your per-model rates.
// Caveat:   Token-derived ESTIMATE; reconcile with Azure Cost Management.

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok  = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"]),
         agent  = tostring(customDimensions["gen_ai.agent.name"])
| summarize prompt=sum(inTok), completion=sum(outTok),
            total=count(), ok=countif(success == true) by agent
| extend est_usd        = round(prompt/1000000.0*0.25 + completion/1000000.0*2.00, 4),
         success_rate   = round(100.0 * ok / total, 1)
| extend usd_per_success = round(iff(ok > 0, est_usd / ok, real(null)), 6)
| project agent, total, ok, success_rate, est_usd, usd_per_success
| order by usd_per_success desc

variables.$fxv#4:
// Cached-input token ratio, by agent (last 24h)
// -------------------------------------------------------------------
// Purpose:  Savings lever. Prompt caching bills cached input tokens at a
//           large discount (~88% off). A LOW cached % on agents with big,
//           repeated system prompts = money left on the table.
// Source:   Application Insights `dependencies` (GenAI spans).
// Pricing:  gpt-5-mini Global (Azure OpenAI pricing) input $0.25/1M,
//           cached input $0.03/1M -> each cached token saves $0.22/1M.
//           https://azure.microsoft.com/en-us/pricing/details/azure-openai/
// Notes:    `gen_ai.usage.cached_input_tokens` is only emitted when the
//           model/SDK reports cache hits. If the column is absent it reads
//           as 0 -> cached_pct 0 (i.e., no caching in effect = opportunity).

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok   = toint(customDimensions["gen_ai.usage.input_tokens"]),
         cached  = toint(customDimensions["gen_ai.usage.cached_input_tokens"]),
         agent   = tostring(customDimensions["gen_ai.agent.name"])
| summarize input=sum(inTok), cached=sum(coalesce(cached, 0)) by agent
| extend cached_pct = round(100.0 * todouble(cached) / iff(input > 0, input, 1), 1)
// Savings = cached tokens billed at $0.03/1M instead of $0.25/1M.
| extend est_savings_usd = round(todouble(cached) * (0.25 - 0.03) / 1000000.0, 4)
| project agent, input, cached, cached_pct, est_savings_usd
| order by cached_pct asc

