// Model router — routed-model distribution (last 24h)
// -------------------------------------------------------------------
// Purpose:  Show which underlying model the Foundry Model Router picked
//           per request — the portal guidance's "split metrics by the
//           underlying model". A healthy Balanced router sends easy prompts
//           to cheap models and only escalates hard ones.
//           https://learn.microsoft.com/azure/foundry/openai/how-to/model-router#monitor-model-router-metrics
// Source:   Application Insights `dependencies` (GenAI spans).
//   gen_ai.request.model  = 'model-router'   (the deployment that was called)
//   gen_ai.response.model = <routed model>   (who actually answered)
// Pricing:  placeholder gpt-5-mini rates for the est. cost column.
dependencies
| where timestamp > ago(1d)
      and tostring(customDimensions["gen_ai.request.model"]) == "model-router"
| extend routed  = tostring(customDimensions["gen_ai.response.model"]),
         inTok   = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok  = toint(customDimensions["gen_ai.usage.output_tokens"])
| summarize calls = count(), input = sum(inTok), output = sum(outTok) by routed
| as T
| extend pct_calls    = round(100.0 * calls / toscalar(T | summarize sum(calls)), 1),
         est_cost_usd = round((input * 0.25 + output * 2.0) / 1000000.0, 4)
| project routed, calls, pct_calls, input, output, est_cost_usd
| order by calls desc

variables.$fxv#6:
// Truncated-response rate (finish_reason = "length"), by agent (last 24h)
// -------------------------------------------------------------------
// Purpose:  Token-waste + quality signal. A high share of responses that
//           stop because they hit the max-output-token limit ("length")
//           means answers are being cut off AND you're paying for the
//           maximum output every time — the verbosity red flag.
// Source:   Application Insights `dependencies` (GenAI spans),
//           `gen_ai.response.finish_reasons` (JSON array serialized to text).
// Action:   High % -> raise max_tokens OR (better) make the agent terser.

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend agent = tostring(customDimensions["gen_ai.agent.name"]),
         fr    = tostring(customDimensions["gen_ai.response.finish_reasons"])
| summarize total=count(), truncated=countif(fr has "length") by agent
| extend truncated_pct = round(100.0 * truncated / total, 1)
| project agent, total, truncated, truncated_pct
| order by truncated_pct desc

variables.$fxv#7:
// Latency percentiles by agent (last 24h)
// -------------------------------------------------------------------
// Purpose:  Performance view. p50/p95/p99 end-to-end duration per agent —
//           the UX signal, and a cost proxy (long generations = more output
//           tokens). Tail latency (p95/p99) is what users actually feel.
// Source:   Application Insights `dependencies`; native `duration` column
//           is milliseconds. Attributable (agent) spans only.
// Tip:      Add `| render columnchart` to visualize in the portal Logs blade.

dependencies
| where timestamp > ago(1d)
      and isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend agent = tostring(customDimensions["gen_ai.agent.name"])
| summarize p50_ms=round(percentile(duration, 50), 0),
            p95_ms=round(percentile(duration, 95), 0),
            p99_ms=round(percentile(duration, 99), 0),
            calls=count() by agent
| order by p95_ms desc

variables.$fxv#8:
// Tool call volume & error rate, by tool (last 24h)
// -------------------------------------------------------------------
// Purpose:  Agent-specific health. Which tools are hot, and which fail —
//           a high tool error rate usually means a poor tool/parameter
//           description (an Agent-Optimizer 'tool optimization' target) and
//           drives wasted retries + tokens.
// Source:   Application Insights `dependencies`; tool-execution GenAI spans
//           (gen_ai.operation.name == "execute_tool" or gen_ai.tool.name set).
// Note:     Only populates when agents actually call tools. The basic demo
//           agents have no tools, so expect empty until tool-using agents run.

dependencies
| where timestamp > ago(1d)
| where tostring(customDimensions["gen_ai.operation.name"]) == "execute_tool"
      or isnotempty(tostring(customDimensions["gen_ai.tool.name"]))
| extend tool = tostring(customDimensions["gen_ai.tool.name"])
| summarize calls=count(), failures=countif(success == false),
            avg_ms=round(avg(duration), 0) by tool
| extend error_rate_pct = round(100.0 * failures / calls, 1)
| project tool, calls, failures, error_rate_pct, avg_ms
| order by error_rate_pct desc, calls desc

variables.$fxv#9:
// PTU vs consumption break-even (last window)
// -------------------------------------------------------------------
// Purpose:  The core PTU FinOps decision. Takes the ACTUAL token volume
//           the agents are producing, projects it to a full day, and
//           compares consumption (pay-go) cost/day against the fixed cost
//           of a Provisioned Throughput (PTU) reservation — and reports the
//           token/day break-even where PTU becomes the cheaper option.
// Source:   Application Insights `dependencies` (GenAI spans).
// Tune:     Edit the four `let` values below. ptuHourlyUsd/ptuCount drive
//           the fixed side; inPrice/outPrice the consumption side.
// Reality:  At the current demo volume (~$0.27/day) you are FAR below PTU
//           break-even — small/bursty workloads belong on consumption;
//           steady high-volume belongs on PTU. That contrast IS the lesson.
// Caveat:   Estimate only. Real PTU pricing has minimums (often 15-50 PTU/
//           deployment) and monthly/annual reservations are cheaper than
//           hourly. Reconcile with Azure pricing + Cost Management.

let ptuCount      = 15;     // PTU reserved (typical per-deployment minimum)
let ptuHourlyUsd  = 1.0;    // ~list hourly $/PTU; use your reservation rate
let inPrice       = 0.25;   // consumption price: USD / 1M input tokens
let outPrice      = 2.00;   // consumption price: USD / 1M output tokens
dependencies
| where isnotempty(tostring(customDimensions["gen_ai.agent.name"]))
| extend inTok  = toint(customDimensions["gen_ai.usage.input_tokens"]),
         outTok = toint(customDimensions["gen_ai.usage.output_tokens"])
| summarize prompt=sum(inTok), completion=sum(outTok),
            firstT=min(timestamp), lastT=max(timestamp)
| extend windowHours     = max_of(todouble(datetime_diff('second', lastT, firstT)) / 3600.0, 1.0),
         total_tokens    = prompt + completion,
         consumption_usd = prompt/1000000.0*inPrice + completion/1000000.0*outPrice
| extend tokens_per_day        = round(total_tokens / windowHours * 24, 0),
         consumption_usd_day   = round(consumption_usd / windowHours * 24, 2),
         ptu_usd_day           = round(ptuCount * ptuHourlyUsd * 24, 2),
         price_per_token       = consumption_usd / iff(total_tokens > 0, total_tokens, 1)
| extend breakeven_tokens_day  = round(ptu_usd_day / iff(price_per_token > 0, price_per_token, 1.0), 0),
         verdict               = iff(consumption_usd_day >= ptu_usd_day,
                                     'PTU cheaper at current volume',
                                     'Consumption cheaper — stay pay-go')
| project tokens_per_day, breakeven_tokens_day, consumption_usd_day, ptu_usd_day, verdict
